// The network answer is never aborted. A packaged worker keeps its installed generation intact; only a complete
// install may replace it. An unstamped development worker can still warm resources as they are read.
function fromNetwork(event, request) {
  var network = fetch(request).then(function (response) {
    if (response.status < 500 || response.status > 599) storeFor(event, request, response);
    return response;
  });
  try {
    event.waitUntil(
      network.catch(function () {
        // offline: the cache answers
      })
    );
  } catch {
    // The event already finished; the fetch still runs while the worker lives.
  }
  return network;
}

/** Rejects after `ms`, so a slow network can give way to the cached shell. */
function giveUpAfter(ms) {
  return new Promise(function (resolve, reject) {
    setTimeout(function () {
      reject(new Error('The network was too slow; the cached shell answers.'));
    }, ms);
  });
}

// Stores a copy of a fetched response. The copies are cloned right away, before
// the original goes back to the page and its body is read; cloning later, after
// the cache opened, failed silently and left the cache empty.
function store(request, response) {
  if (PRECACHE.length > 0 || request.cache === 'no-store' || !AacSwRoute.cacheable(response))
    return Promise.resolve();
  var copy = response.clone();
  var mirror = null;
  try {
    var url = new URL(request.url);
    if (
      AacSwRoute.shouldMirrorStartUrl(
        {
          method: request.method,
          sameOrigin: url.origin === self.location.origin,
          pathname: url.pathname,
          isNavigation: request.mode === 'navigate',
        },
        response
      )
    ) {
      // Every page route serves the same index.html: mirror it under the
      // start URL, so the installed app's first offline launch finds a shell.
      mirror = new URL(AacSwRoute.START_URL_PATHNAME, url.origin).toString();
    }
  } catch {
    mirror = null;
  }
  // A separate copy per entry; the original stays with the page.
  var mirrorCopy = mirror ? response.clone() : null;
  return caches
    .open(CACHE)
    .then(function (cache) {
      var puts = [cache.put(request, copy)];
      if (mirror) puts.push(cache.put(mirror, mirrorCopy));
      return Promise.all(puts);
    })
    .catch(function () {});
